def f(I, mode='center'):
    I=np.array(I); H,W=I.shape
    cnt=Counter(I.flat); excl={c for c,_ in cnt.most_common()[:2]}
    OH=round(H/3); OW=round(W/3)
    O=np.zeros((OH,OW),int)
    for c in cnt:
        if c in excl: continue
        rs,cs=np.where(I==c)
        cr,cc=rs.mean(),cs.mean()
        if mode=='center':
            r=int(round(cr*(OH-1)/(H-1))); k=int(round(cc*(OW-1)/(W-1)))
        elif mode=='min_div':
            r=int(np.floor(rs.min())//(H//OH)); k=int(np.floor(cs.min())//(W//OW))
        else:
            r=int(np.floor(cr*OH/H)); k=int(np.floor(cc*OW/W))
        O[r,k]=c
    return O.tolist()
